export const COMPONENT_TYPES = [
…
] as const;

export type ComponentType = (typeof COMPONENT_TYPES)[number];
/** One canvas, two modes: you are either drawing the app or using it. */
export type WorkspaceMode = "draw" | "run";

export interface Point { … }

export interface InkStroke { … }

export interface Bounds { … }

export interface AppComponent { … }

export type ActionType =
  | "setState"
  | "filter"
  | "sort"
  | "validate"
  | "open"
  | "close"
  | "navigate"
  | "fetch"
  | "create"
  | "update"
  | "delete"
  | "visibility"
  | "custom";

export interface BehaviorEdge { … }

export interface AppGraph { … }

export interface AgentComponent { … }

export interface AgentEdge { … }

export interface ProcessResponse { … }

export const EMPTY_GRAPH: AppGraph = { … };

export function createId(prefix: string): string { … }

export function getStrokeBounds(stroke: InkStroke): Bounds { … }

export function guessComponentType(bounds: Bounds): ComponentType { … }

export function defaultProps(type: ComponentType): AppComponent["props"] { … }

export function isClosedShape(stroke: InkStroke): boolean { … }

export function hitTest(
  point: Point,
  component: AppComponent,
  padding = 0,
): boolean { … }

export function sanitizeComponentType(value: string): ComponentType { … }

export function sanitizeActionType(value: string): ActionType { … }

export function componentLabel(component: AppComponent): string { … }

export function localHandler(
  source: AppComponent,
  target: AppComponent,
): Pick<
  BehaviorEdge,
  "instruction" | "triggerEvent" | "actionType" | "sourceData" | "predicate" | "handler" | "tests"
> { … }

/** State key controlling whether an overlay component is visible. */
export function openKey(componentId: string): string {
  return `open:${componentId}`;
}

