                    <input
                      type="radio"
                      name="engine"
                      value={value}
                      checked={engine === value}
                      onChange={() => setEngine(value)}
                    />
                    <span>
                      <strong>{value}</strong>
                      <small>
                        {agentStatus === null
                          ? "bridge offline"
                          : agentStatus.available[value]
                            ? "ready"
                            : "not installed"}
                      </small>
                    </span>
                  </label>
                ))}
              </fieldset>
              <label className="field">
                <span>Model</span>
                <input
                  value={models[engine]}
                  onChange={(event) =>
                    setModels((current) => ({
                      ...current,
                      [engine]: event.target.value,
                    }))
                  }
                  spellCheck={false}
                />
              </label>
              <div className="bridge-state">
                <span
                  className={`bridge-dot ${
                    agentStatus?.available[engine] ? "is-online" : ""
                  }`}
                />
                {agentStatus === null
                  ? "Bridge offline — the local shape matcher will be used."
                  : agentStatus.available[engine]
                    ? `${engine} is ready`
                    : `${engine} is not on PATH — the local shape matcher will be used.`}
              </div>
              <button
                type="button"
                className="secondary-button"
                onClick={() => void refreshAgentStatus()}
              >
                Check again
              </button>
              <p className="shortcut-note">
                ⌘Enter process · ⌘R draw/run · ⌘Z undo
              </p>
            </div>
          )}
        </aside>
      )}
    </main>
  );
}

